<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>鹈鹕海边骑车</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        body {
            background: #1a2a3a;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            font-family: sans-serif;
        }
        canvas {
            border-radius: 16px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
            display: block;
            max-width: 100vw;
            max-height: 100vh;
            width: auto;
            height: auto;
        }
    </style>
</head>
<body>
    <canvas id="c"></canvas>
    <script>
        (function() {
            const canvas = document.getElementById('c');
            const ctx = canvas.getContext('2d');

            const W = 900;
            const H = 560;
            canvas.width = W;
            canvas.height = H;

            // 场景参数
            const SEA_TOP = 210;
            const SEA_BOT = 310;
            const ROAD_TOP = 340;
            const ROAD_BOT = 480;

            // 自行车参数
            const REAR_X = 340,
                REAR_Y = 450,
                REAR_R = 34;
            const FRONT_X = 480,
                FRONT_Y = 450,
                FRONT_R = 34;
            const PEDAL_CX = (REAR_X + FRONT_X) / 2;
            const PEDAL_CY = REAR_Y + 4;
            const PEDAL_R = 22;
            const SEAT_X = REAR_X + 28;
            const SEAT_Y = REAR_Y - 70;
            const HANDLE_X = FRONT_X - 18;
            const HANDLE_Y = FRONT_Y - 78;

            // 鹈鹕身体参数
            const BODY_CX = SEAT_X + 2;
            const BODY_CY = SEAT_Y - 38;
            const BODY_RX = 48;
            const BODY_RY = 34;

            // 动画状态
            let time = 0;
            let pedalAngle = 0;
            let wheelAngle = 0;
            let wingAngle = 0;
            let scrollOffset = 0;

            // 云朵
            const clouds = [];
            for (let i = 0; i < 8; i++) {
                clouds.push({
                    x: Math.random() * W,
                    y: 30 + Math.random() * 140,
                    w: 60 + Math.random() * 100,
                    h: 25 + Math.random() * 35,
                    speed: 0.15 + Math.random() * 0.25,
                    alpha: 0.6 + Math.random() * 0.3
                });
            }

            // 海浪点
            const wavePoints = [];
            for (let i = 0; i < 50; i++) {
                wavePoints.push({
                    x: i * 20,
                    y: 0,
                    amp: 4 + Math.random() * 8,
                    freq: 0.02 + Math.random() * 0.03,
                    phase: Math.random() * Math.PI * 2
                });
            }

            // 路边棕榈树（简化）
            const trees = [];
            for (let i = 0; i < 6; i++) {
                trees.push({
                    x: i * 200 + 40,
                    trunkH: 60 + Math.random() * 30,
                    leafR: 22 + Math.random() * 12,
                    color: `hsl(${120 + Math.random()*20}, 55%, ${30 + Math.random()*20}%)`
                });
            }

            // 公路车道线
            const roadMarks = [];
            for (let i = 0; i < 30; i++) {
                roadMarks.push({
                    x: i * 60,
                    w: 30,
                    y: ROAD_TOP + (ROAD_BOT - ROAD_TOP) / 2 - 2
                });
            }

            // 海面反光
            const glints = [];
            for (let i = 0; i < 20; i++) {
                glints.push({
                    x: Math.random() * W,
                    y: SEA_TOP + Math.random() * (SEA_BOT - SEA_TOP),
                    size: 2 + Math.random() * 5,
                    speed: 0.3 + Math.random() * 0.5,
                    alpha: 0.1 + Math.random() * 0.3
                });
            }

            // ===== 绘制函数 =====

            function drawSky() {
                const grad = ctx.createLinearGradient(0, 0, 0, SEA_TOP);
                grad.addColorStop(0, '#4a8cce');
                grad.addColorStop(0.4, '#7bb5e0');
                grad.addColorStop(0.7, '#b5d8f0');
                grad.addColorStop(1, '#e8f4fd');
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, W, SEA_TOP + 10);

                // 太阳
                const sunX = W - 120 + Math.sin(time * 0.008) * 20;
                const sunY = 60 + Math.sin(time * 0.01) * 8;
                const grad2 = ctx.createRadialGradient(sunX, sunY, 5, sunX, sunY, 55);
                grad2.addColorStop(0, '#fffbe6');
                grad2.addColorStop(0.3, '#ffe680');
                grad2.addColorStop(0.6, '#ffb347');
                grad2.addColorStop(1, 'rgba(255,180,80,0)');
                ctx.fillStyle = grad2;
                ctx.beginPath();
                ctx.arc(sunX, sunY, 55, 0, Math.PI * 2);
                ctx.fill();

                ctx.fillStyle = '#fff9e0';
                ctx.beginPath();
                ctx.arc(sunX, sunY, 24, 0, Math.PI * 2);
                ctx.fill();

                // 云朵
                clouds.forEach(c => {
                    const cx = ((c.x - scrollOffset * c.speed * 0.6) % (W + 200) + W + 200) % (W + 200) - 100;
                    ctx.globalAlpha = c.alpha;
                    ctx.fillStyle = '#ffffff';
                    ctx.beginPath();
                    ctx.ellipse(cx, c.y, c.w * 0.5, c.h * 0.5, 0, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.beginPath();
                    ctx.ellipse(cx - c.w * 0.25, c.y + c.h * 0.1, c.w * 0.35, c.h * 0.4, 0, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.beginPath();
                    ctx.ellipse(cx + c.w * 0.3, c.y + c.h * 0.05, c.w * 0.3, c.h * 0.35, 0, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.globalAlpha = 1;
                });
            }

            function drawSea() {
                const grad = ctx.createLinearGradient(0, SEA_TOP, 0, SEA_BOT);
                grad.addColorStop(0, '#3a8fc0');
                grad.addColorStop(0.3, '#2d7aaa');
                grad.addColorStop(0.6, '#1e6a96');
                grad.addColorStop(1, '#1a5a82');
                ctx.fillStyle = grad;
                ctx.fillRect(0, SEA_TOP, W, SEA_BOT - SEA_TOP);

                // 波浪
                ctx.strokeStyle = 'rgba(255,255,255,0.25)';
                ctx.lineWidth = 2;
                for (let row = 0; row < 4; row++) {
                    const baseY = SEA_TOP + 12 + row * 22 + Math.sin(time * 0.02 + row) * 3;
                    ctx.beginPath();
                    for (let x = 0; x <= W; x += 6) {
                        const y = baseY + Math.sin(x * 0.025 + time * 0.03 + row * 1.8) * 6 +
                            Math.sin(x * 0.05 + time * 0.05 + row * 2.5) * 3;
                        if (x === 0) ctx.moveTo(x, y);
                        else ctx.lineTo(x, y);
                    }
                    ctx.stroke();
                }

                // 海面反光
                glints.forEach(g => {
                    const gx = ((g.x - scrollOffset * 0.1) % (W + 40) + W + 40) % (W + 40) - 20;
                    const gy = g.y + Math.sin(time * 0.02 + g.x * 0.01) * 4;
                    ctx.globalAlpha = g.alpha * (0.7 + Math.sin(time * g.speed + g.x) * 0.3);
                    ctx.fillStyle = '#fffbe6';
                    ctx.beginPath();
                    ctx.ellipse(gx, gy, g.size * 1.2, g.size * 0.5, 0, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.globalAlpha = 1;
                });

                // 海岸线（沙滩）
                const sandGrad = ctx.createLinearGradient(0, SEA_BOT - 4, 0, ROAD_TOP + 6);
                sandGrad.addColorStop(0, '#d4b87a');
                sandGrad.addColorStop(0.5, '#e8d5a8');
                sandGrad.addColorStop(1, '#f0e6c8');
                ctx.fillStyle = sandGrad;
                ctx.fillRect(0, SEA_BOT - 4, W, ROAD_TOP - SEA_BOT + 8);
            }

            function drawRoad() {
                // 公路主体
                const grad = ctx.createLinearGradient(0, ROAD_TOP, 0, ROAD_BOT);
                grad.addColorStop(0, '#6a6a6a');
                grad.addColorStop(0.15, '#7a7a7a');
                grad.addColorStop(0.5, '#8a8a8a');
                grad.addColorStop(0.85, '#7a7a7a');
                grad.addColorStop(1, '#5a5a5a');
                ctx.fillStyle = grad;
                ctx.fillRect(0, ROAD_TOP, W, ROAD_BOT - ROAD_TOP);

                // 路肩线（白色）
                ctx.strokeStyle = '#f0f0f0';
                ctx.lineWidth = 3;
                ctx.setLineDash([]);
                ctx.beginPath();
                ctx.moveTo(0, ROAD_TOP + 6);
                ctx.lineTo(W, ROAD_TOP + 6);
                ctx.stroke();
                ctx.beginPath();
                ctx.moveTo(0, ROAD_BOT - 6);
                ctx.lineTo(W, ROAD_BOT - 6);
                ctx.stroke();

                // 车道线（虚线，滚动）
                ctx.strokeStyle = '#f8f8f8';
                ctx.lineWidth = 4;
                ctx.setLineDash([30, 25]);
                const dashOffset = -(scrollOffset * 1.2) % 55;
                ctx.lineDashOffset = dashOffset;
                const midY = ROAD_TOP + (ROAD_BOT - ROAD_TOP) / 2;
                ctx.beginPath();
                ctx.moveTo(0, midY);
                ctx.lineTo(W, midY);
                ctx.stroke();
                ctx.setLineDash([]);
                ctx.lineDashOffset = 0;

                // 路面纹理（小点）
                ctx.fillStyle = 'rgba(255,255,255,0.04)';
                for (let i = 0; i < 50; i++) {
                    const tx = ((i * 37 + 13) % W - scrollOffset * 1.1) % W;
                    const ty = ROAD_TOP + 12 + ((i * 23 + 7) % (ROAD_BOT - ROAD_TOP - 24));
                    ctx.beginPath();
                    ctx.arc(tx, ty, 1.5, 0, Math.PI * 2);
                    ctx.fill();
                }

                // 路边碎石/小草
                for (let i = 0; i < 30; i++) {
                    const gx = ((i * 41 + 19) % W - scrollOffset * 0.8) % W;
                    const gy = ROAD_BOT - 4 + ((i * 17 + 11) % 14) - 6;
                    ctx.fillStyle = `hsl(${100 + (i*7)%30}, 40%, ${35 + (i*5)%20}%)`;
                    ctx.beginPath();
                    ctx.ellipse(gx, gy, 3 + (i % 4), 2 + (i % 3), 0, 0, Math.PI * 2);
                    ctx.fill();
                }
            }

            function drawTrees() {
                trees.forEach((t, idx) => {
                    const tx = ((t.x - scrollOffset * 0.2) % (W + 200) + W + 200) % (W + 200) - 100;
                    const ty = ROAD_BOT - 6;

                    // 树干
                    ctx.fillStyle = '#6b4c2a';
                    ctx.fillRect(tx - 4, ty - t.trunkH, 8, t.trunkH);

                    // 树叶（多层）
                    const leafColors = ['#3a7a2a', '#4a8a3a', '#5a9a4a', '#2a6a1a'];
                    for (let i = 0; i < 4; i++) {
                        const lr = t.leafR * (1 - i * 0.15);
                        const ly = ty - t.trunkH - i * 8 + Math.sin(time * 0.01 + idx + i) * 2;
                        ctx.fillStyle = leafColors[i % leafColors.length];
                        ctx.beginPath();
                        ctx.ellipse(tx, ly, lr * 1.2, lr * 0.9, 0.2 + i * 0.1, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    // 高光
                    ctx.fillStyle = 'rgba(180,230,140,0.2)';
                    ctx.beginPath();
                    ctx.ellipse(tx + t.leafR * 0.3, ty - t.trunkH - 8, t.leafR * 0.5, t.leafR * 0.3, 0.3, 0, Math.PI * 2);
                    ctx.fill();
                });
            }

            function drawBicycle(angle) {
                const wAngle = angle * 2.6;

                // ---- 后轮 ----
                drawWheel(REAR_X, REAR_Y, REAR_R, wAngle);

                // ---- 前轮 ----
                drawWheel(FRONT_X, FRONT_Y, FRONT_R, wAngle);

                // ---- 车架 ----
                ctx.strokeStyle = '#3a4a5a';
                ctx.lineWidth = 5;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';

                // 主三角：后轴→车座→中轴
                ctx.beginPath();
                ctx.moveTo(REAR_X, REAR_Y);
                ctx.lineTo(SEAT_X, SEAT_Y);
                ctx.lineTo(PEDAL_CX, PEDAL_CY);
                ctx.closePath();
                ctx.stroke();

                // 前三角：中轴→车把→前轴
                ctx.beginPath();
                ctx.moveTo(PEDAL_CX, PEDAL_CY);
                ctx.lineTo(HANDLE_X, HANDLE_Y);
                ctx.lineTo(FRONT_X, FRONT_Y);
                ctx.closePath();
                ctx.stroke();

                // 连接：车座→后轴（加强）
                ctx.beginPath();
                ctx.moveTo(SEAT_X, SEAT_Y);
                ctx.lineTo(REAR_X, REAR_Y - 8);
                ctx.stroke();

                // 连接：中轴→后轴下
                ctx.beginPath();
                ctx.moveTo(PEDAL_CX, PEDAL_CY);
                ctx.lineTo(REAR_X + 4, REAR_Y + 6);
                ctx.stroke();

                // 车座
                ctx.fillStyle = '#2a2a3a';
                ctx.beginPath();
                ctx.ellipse(SEAT_X, SEAT_Y - 4, 18, 7, 0.1, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = '#4a4a5a';
                ctx.beginPath();
                ctx.ellipse(SEAT_X, SEAT_Y - 5, 14, 5, 0.1, 0, Math.PI * 2);
                ctx.fill();

                // 车把
                ctx.strokeStyle = '#3a4a5a';
                ctx.lineWidth = 5;
                ctx.beginPath();
                ctx.moveTo(HANDLE_X, HANDLE_Y);
                ctx.lineTo(HANDLE_X + 22, HANDLE_Y - 18);
                ctx.stroke();
                ctx.beginPath();
                ctx.moveTo(HANDLE_X, HANDLE_Y);
                ctx.lineTo(HANDLE_X + 18, HANDLE_Y + 6);
                ctx.stroke();
                // 车把胶套
                ctx.fillStyle = '#2a2a3a';
                ctx.beginPath();
                ctx.ellipse(HANDLE_X + 22, HANDLE_Y - 18, 6, 5, 0.3, 0, Math.PI * 2);
                ctx.fill();
                ctx.beginPath();
                ctx.ellipse(HANDLE_X + 18, HANDLE_Y + 6, 6, 5, -0.2, 0, Math.PI * 2);
                ctx.fill();

                // ---- 踏板系统 ----
                const p1Angle = angle;
                const p2Angle = angle + Math.PI;

                const p1x = PEDAL_CX + Math.cos(p1Angle) * PEDAL_R;
                const p1y = PEDAL_CY + Math.sin(p1Angle) * PEDAL_R;
                const p2x = PEDAL_CX + Math.cos(p2Angle) * PEDAL_R;
                const p2y = PEDAL_CY + Math.sin(p2Angle) * PEDAL_R;

                // 中轴
                ctx.fillStyle = '#4a4a5a';
                ctx.beginPath();
                ctx.arc(PEDAL_CX, PEDAL_CY, 6, 0, Math.PI * 2);
                ctx.fill();

                // 曲柄
                ctx.strokeStyle = '#4a4a5a';
                ctx.lineWidth = 4;
                ctx.beginPath();
                ctx.moveTo(PEDAL_CX, PEDAL_CY);
                ctx.lineTo(p1x, p1y);
                ctx.stroke();
                ctx.beginPath();
                ctx.moveTo(PEDAL_CX, PEDAL_CY);
                ctx.lineTo(p2x, p2y);
                ctx.stroke();

                // 踏板
                ctx.fillStyle = '#3a3a3a';
                ctx.save();
                ctx.translate(p1x, p1y);
                ctx.rotate(p1Angle);
                ctx.fillRect(-10, -3, 20, 6);
                ctx.restore();
                ctx.save();
                ctx.translate(p2x, p2y);
                ctx.rotate(p2Angle);
                ctx.fillRect(-10, -3, 20, 6);
                ctx.restore();

                // 链条（装饰）
                ctx.strokeStyle = 'rgba(60,60,70,0.3)';
                ctx.lineWidth = 2;
                ctx.setLineDash([4, 6]);
                ctx.lineDashOffset = -angle * 8;
                ctx.beginPath();
                ctx.moveTo(REAR_X + 2, REAR_Y + 4);
                ctx.lineTo(PEDAL_CX - 4, PEDAL_CY + 2);
                ctx.stroke();
                ctx.setLineDash([]);
                ctx.lineDashOffset = 0;

                // 返回踏板位置供鹈鹕腿使用
                return { p1: { x: p1x, y: p1y }, p2: { x: p2x, y: p2y } };
            }

            function drawWheel(cx, cy, r, angle) {
                // 轮胎
                ctx.fillStyle = '#2a2a2a';
                ctx.beginPath();
                ctx.arc(cx, cy, r, 0, Math.PI * 2);
                ctx.fill();

                // 外胎纹理
                ctx.strokeStyle = '#3a3a3a';
                ctx.lineWidth = 3;
                ctx.beginPath();
                ctx.arc(cx, cy, r - 2, 0, Math.PI * 2);
                ctx.stroke();

                // 内圈
                ctx.fillStyle = '#4a4a4a';
                ctx.beginPath();
                ctx.arc(cx, cy, r * 0.6, 0, Math.PI * 2);
                ctx.fill();

                // 辐条
                ctx.strokeStyle = '#8a8a8a';
                ctx.lineWidth = 1.8;
                for (let i = 0; i < 12; i++) {
                    const a = angle + i * Math.PI / 6;
                    ctx.beginPath();
                    ctx.moveTo(cx + Math.cos(a) * r * 0.2, cy + Math.sin(a) * r * 0.2);
                    ctx.lineTo(cx + Math.cos(a) * r * 0.85, cy + Math.sin(a) * r * 0.85);
                    ctx.stroke();
                }

                // 花鼓
                ctx.fillStyle = '#6a6a6a';
                ctx.beginPath();
                ctx.arc(cx, cy, r * 0.18, 0, Math.PI * 2);
                ctx.fill();

                // 轮胎高光
                ctx.strokeStyle = 'rgba(255,255,255,0.12)';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(cx - r * 0.2, cy - r * 0.2, r * 0.9, -0.8, 0.4);
                ctx.stroke();

                // 胎纹
                ctx.strokeStyle = 'rgba(60,60,60,0.4)';
                ctx.lineWidth = 1.5;
                for (let i = 0; i < 24; i++) {
                    const a = angle + i * Math.PI / 12;
                    const outer = r - 1;
                    const inner = r - 6;
                    ctx.beginPath();
                    ctx.moveTo(cx + Math.cos(a) * inner, cy + Math.sin(a) * inner);
                    ctx.lineTo(cx + Math.cos(a) * outer, cy + Math.sin(a) * outer);
                    ctx.stroke();
                }
            }

            function drawPelican(angle, pedalPositions) {
                const wingFlap = Math.sin(wingAngle) * 0.4;
                const bodyBob = Math.sin(angle * 2) * 1.5;

                const bcx = BODY_CX;
                const bcy = BODY_CY + bodyBob;

                // ---- 身体 ----
                ctx.fillStyle = '#f0ede8';
                ctx.beginPath();
                ctx.ellipse(bcx, bcy, BODY_RX, BODY_RY, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.strokeStyle = '#d0ccc8';
                ctx.lineWidth = 1.5;
                ctx.stroke();

                // 身体阴影
                ctx.fillStyle = 'rgba(180,175,170,0.2)';
                ctx.beginPath();
                ctx.ellipse(bcx + 6, bcy + 8, BODY_RX * 0.7, BODY_RY * 0.5, 0.2, 0, Math.PI * 2);
                ctx.fill();

                // ---- 尾巴 ----
                ctx.fillStyle = '#d8d4d0';
                ctx.beginPath();
                ctx.moveTo(bcx - BODY_RX * 0.85, bcy - 4);
                ctx.quadraticCurveTo(bcx - BODY_RX * 1.3, bcy - 16, bcx - BODY_RX * 0.9, bcy - 20);
                ctx.quadraticCurveTo(bcx - BODY_RX * 0.7, bcy - 14, bcx - BODY_RX * 0.75, bcy - 2);
                ctx.fill();

                // ---- 翅膀 ----
                const wingY = bcy - BODY_RY * 0.5 + wingFlap * 12;
                ctx.fillStyle = '#d8d4d0';
                ctx.beginPath();
                ctx.moveTo(bcx - 6, bcy - BODY_RY * 0.6);
                ctx.quadraticCurveTo(bcx + 10, wingY - 32, bcx + 40, wingY - 18);
                ctx.quadraticCurveTo(bcx + 30, wingY - 8, bcx + 8, bcy - BODY_RY * 0.2);
                ctx.fill();
                // 翅膀层次
                ctx.fillStyle = 'rgba(200,196,190,0.5)';
                ctx.beginPath();
                ctx.moveTo(bcx - 2, bcy - BODY_RY * 0.5);
                ctx.quadraticCurveTo(bcx + 16, wingY - 26, bcx + 38, wingY - 14);
                ctx.quadraticCurveTo(bcx + 26, wingY - 4, bcx + 6, bcy - BODY_RY * 0.15);
                ctx.fill();

                // 翅膀羽毛纹理
                ctx.strokeStyle = 'rgba(180,176,170,0.3)';
                ctx.lineWidth = 1;
                for (let i = 0; i < 5; i++) {
                    const fx = bcx + 12 + i * 7;
                    const fy = wingY - 16 + i * 3 + Math.sin(i * 0.8) * 4;
                    ctx.beginPath();
                    ctx.moveTo(fx - 4, fy + 4);
                    ctx.quadraticCurveTo(fx + 2, fy - 6, fx + 10, fy - 2);
                    ctx.stroke();
                }

                // ---- 头 ----
                const headX = bcx + BODY_RX * 0.7;
                const headY = bcy - BODY_RY * 0.55;
                const headR = 19;
                ctx.fillStyle = '#f5f2ee';
                ctx.beginPath();
                ctx.arc(headX, headY, headR, 0, Math.PI * 2);
                ctx.fill();
                ctx.strokeStyle = '#d8d4d0';
                ctx.lineWidth = 1.5;
                ctx.stroke();

                // 头阴影
                ctx.fillStyle = 'rgba(200,196,190,0.15)';
                ctx.beginPath();
                ctx.arc(headX + 3, headY + 4, headR * 0.7, 0, Math.PI * 2);
                ctx.fill();

                // ---- 眼睛 ----
                const eyeX = headX + 8;
                const eyeY = headY - 3;
                ctx.fillStyle = '#1a1a1a';
                ctx.beginPath();
                ctx.arc(eyeX, eyeY, 4.5, 0, Math.PI * 2);
                ctx.fill();
                // 高光
                ctx.fillStyle = '#ffffff';
                ctx.beginPath();
                ctx.arc(eyeX + 2, eyeY - 2, 2, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = 'rgba(255,255,255,0.3)';
                ctx.beginPath();
                ctx.arc(eyeX + 1, eyeY + 2, 1.2, 0, Math.PI * 2);
                ctx.fill();

                // 眼圈（黑色眼影）
                ctx.strokeStyle = 'rgba(60,50,40,0.2)';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(eyeX, eyeY, 6, 0, Math.PI * 2);
                ctx.stroke();

                // ---- 嘴（鹈鹕标志性大嘴） ----
                const mouthX = headX + 14;
                const mouthY = headY + 2;

                // 上嘴
                ctx.fillStyle = '#e8a830';
                ctx.beginPath();
                ctx.moveTo(mouthX, mouthY - 1);
                ctx.quadraticCurveTo(mouthX + 42, mouthY - 8, mouthX + 58, mouthY - 2);
                ctx.quadraticCurveTo(mouthX + 56, mouthY + 2, mouthX + 42, mouthY + 2);
                ctx.quadraticCurveTo(mouthX + 20, mouthY + 2, mouthX, mouthY + 1);
                ctx.fill();

                // 上嘴线
                ctx.strokeStyle = '#c08020';
                ctx.lineWidth = 1.5;
                ctx.beginPath();
                ctx.moveTo(mouthX, mouthY - 1);
                ctx.quadraticCurveTo(mouthX + 42, mouthY - 8, mouthX + 58, mouthY - 2);
                ctx.stroke();

                // 喉囊（大而下垂）
                ctx.fillStyle = '#f0b848';
                ctx.beginPath();
                ctx.moveTo(mouthX + 4, mouthY + 2);
                ctx.quadraticCurveTo(mouthX + 20, mouthY + 36, mouthX + 40, mouthY + 28);
                ctx.quadraticCurveTo(mouthX + 50, mouthY + 20, mouthX + 44, mouthY + 6);
                ctx.quadraticCurveTo(mouthX + 30, mouthY + 10, mouthX + 4, mouthY + 2);
                ctx.fill();

                // 喉囊高光
                ctx.fillStyle = 'rgba(255,220,140,0.3)';
                ctx.beginPath();
                ctx.moveTo(mouthX + 10, mouthY + 6);
                ctx.quadraticCurveTo(mouthX + 24, mouthY + 24, mouthX + 36, mouthY + 18);
                ctx.quadraticCurveTo(mouthX + 28, mouthY + 12, mouthX + 10, mouthY + 6);
                ctx.fill();

                // 喉囊纹理线
                ctx.strokeStyle = 'rgba(200,160,80,0.2)';
                ctx.lineWidth = 1;
                for (let i = 0; i < 3; i++) {
                    const lx = mouthX + 12 + i * 10;
                    ctx.beginPath();
                    ctx.moveTo(lx, mouthY + 6 + i * 4);
                    ctx.quadraticCurveTo(lx + 6, mouthY + 18 + i * 2, lx + 12, mouthY + 12 + i * 2);
                    ctx.stroke();
                }

                // 下嘴边缘
                ctx.strokeStyle = '#d09030';
                ctx.lineWidth = 1.5;
                ctx.beginPath();
                ctx.moveTo(mouthX + 4, mouthY + 2);
                ctx.quadraticCurveTo(mouthX + 20, mouthY + 36, mouthX + 40, mouthY + 28);
                ctx.quadraticCurveTo(mouthX + 50, mouthY + 20, mouthX + 44, mouthY + 6);
                ctx.stroke();

                // 嘴尖
                ctx.fillStyle = '#d09020';
                ctx.beginPath();
                ctx.arc(mouthX + 56, mouthY - 1, 3, 0, Math.PI * 2);
                ctx.fill();

                // ---- 腿 ----
                if (pedalPositions) {
                    const hipX = bcx - 6;
                    const hipY = bcy + BODY_RY * 0.55;

                    // 左腿 → 踏板1
                    const p1 = pedalPositions.p1;
                    const p2 = pedalPositions.p2;

                    // 判断哪个踏板在前/后，让腿自然交叉
                    const leg1 = p1;
                    const leg2 = p2;

                    // 腿1
                    ctx.strokeStyle = '#e8a830';
                    ctx.lineWidth = 5;
                    ctx.lineCap = 'round';
                    ctx.beginPath();
                    ctx.moveTo(hipX - 4, hipY);
                    ctx.quadraticCurveTo(
                        (hipX + leg1.x) / 2 - 6,
                        (hipY + leg1.y) / 2 - 4,
                        leg1.x, leg1.y - 2
                    );
                    ctx.stroke();

                    // 腿2
                    ctx.strokeStyle = '#d89428';
                    ctx.lineWidth = 5;
                    ctx.beginPath();
                    ctx.moveTo(hipX + 4, hipY);
                    ctx.quadraticCurveTo(
                        (hipX + leg2.x) / 2 + 6,
                        (hipY + leg2.y) / 2 - 2,
                        leg2.x, leg2.y - 2
                    );
                    ctx.stroke();

                    // 脚（固定在踏板上）
                    ctx.fillStyle = '#e8a830';
                    ctx.beginPath();
                    ctx.ellipse(leg1.x, leg1.y - 2, 7, 4, leg1.x > PEDAL_CX ? 0.3 : -0.3, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.beginPath();
                    ctx.ellipse(leg2.x, leg2.y - 2, 7, 4, leg2.x > PEDAL_CX ? 0.3 : -0.3, 0, Math.PI * 2);
                    ctx.fill();

                    // 脚趾
                    ctx.fillStyle = '#d08020';
                    for (let f = 0; f < 3; f++) {
                        const fa = (f - 1) * 0.4 + (leg1.x > PEDAL_CX ? 0.3 : -0.3);
                        ctx.beginPath();
                        ctx.ellipse(
                            leg1.x + Math.cos(fa) * 6,
                            leg1.y - 2 + Math.sin(fa) * 3,
                            3, 2, fa, 0, Math.PI * 2
                        );
                        ctx.fill();
                        const fa2 = (f - 1) * 0.4 + (leg2.x > PEDAL_CX ? 0.3 : -0.3);
                        ctx.beginPath();
                        ctx.ellipse(
                            leg2.x + Math.cos(fa2) * 6,
                            leg2.y - 2 + Math.sin(fa2) * 3,
                            3, 2, fa2, 0, Math.PI * 2
                        );
                        ctx.fill();
                    }
                }

                // ---- 颈部（连接头和身体） ----
                ctx.fillStyle = '#f0ede8';
                ctx.beginPath();
                ctx.moveTo(bcx + BODY_RX * 0.4, bcy - BODY_RY * 0.5);
                ctx.quadraticCurveTo(headX - 4, headY + 6, headX - 2, headY + 2);
                ctx.quadraticCurveTo(bcx + BODY_RX * 0.5, bcy - BODY_RY * 0.2, bcx + BODY_RX * 0.4, bcy - BODY_RY * 0.5);
                ctx.fill();

                // ---- 腮红/装饰 ----
                ctx.fillStyle = 'rgba(255,180,160,0.15)';
                ctx.beginPath();
                ctx.ellipse(headX + 2, headY + 10, 10, 6, 0.2, 0, Math.PI * 2);
                ctx.fill();

                // ---- 头顶小羽毛 ----
                ctx.fillStyle = '#e0dcd8';
                ctx.beginPath();
                ctx.moveTo(headX - 2, headY - headR + 2);
                ctx.quadraticCurveTo(headX - 6, headY - headR - 10, headX + 2, headY - headR - 6);
                ctx.quadraticCurveTo(headX + 6, headY - headR - 2, headX - 2, headY - headR + 2);
                ctx.fill();
            }

            function drawForeground() {
                // 前景路边草丛
                for (let i = 0; i < 40; i++) {
                    const gx = ((i * 37 + 11) % W - scrollOffset * 0.5) % W;
                    const gy = ROAD_BOT + 2 + ((i * 13 + 7) % 18);
                    const h = 12 + (i % 8);
                    const w = 3 + (i % 3);
                    ctx.fillStyle = `hsl(${110 + (i*9)%30}, 50%, ${32 + (i*7)%20}%)`;
                    ctx.beginPath();
                    ctx.ellipse(gx, gy, w, h * 0.5, 0.1 * (i % 3 - 1), 0, Math.PI * 2);
                    ctx.fill();
                    ctx.beginPath();
                    ctx.ellipse(gx + 4 + (i % 5), gy - 2, w * 0.7, h * 0.35, -0.2, 0, Math.PI * 2);
                    ctx.fill();
                }

                // 远处海鸟
                for (let i = 0; i < 5; i++) {
                    const bx = ((i * 137 + 53) % W - scrollOffset * 0.3) % W;
                    const by = SEA_TOP - 20 - (i % 3) * 18 + Math.sin(time * 0.02 + i * 2) * 6;
                    ctx.fillStyle = 'rgba(40,50,60,0.3)';
                    ctx.beginPath();
                    ctx.arc(bx, by, 4, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.beginPath();
                    ctx.arc(bx + 8, by - 2, 3.5, 0, Math.PI * 2);
                    ctx.fill();
                    // 翅膀（V形）
                    ctx.strokeStyle = 'rgba(40,50,60,0.25)';
                    ctx.lineWidth = 1.5;
                    ctx.beginPath();
                    ctx.moveTo(bx + 2, by - 1);
                    ctx.quadraticCurveTo(bx + 6, by - 12, bx + 14, by - 6);
                    ctx.stroke();
                    ctx.beginPath();
                    ctx.moveTo(bx + 6, by - 1);
                    ctx.quadraticCurveTo(bx + 10, by - 14, bx + 18, by - 8);
                    ctx.stroke();
                }
            }

            // ===== 主循环 =====
            function animate(timestamp) {
                const dt = 0.016;
                time += dt;
                pedalAngle += dt * 3.2;
                wheelAngle += dt * 3.2;
                wingAngle += dt * 2.4;
                scrollOffset += dt * 70;

                // 清屏
                ctx.clearRect(0, 0, W, H);

                // 绘制场景
                drawSky();
                drawSea();
                drawRoad();
                drawTrees();

                // 绘制自行车（获取踏板位置）
                const pedals = drawBicycle(pedalAngle);

                // 绘制鹈鹕
                drawPelican(pedalAngle, pedals);

                // 前景装饰
                drawForeground();

                // 底部阴影（自行车下）
                ctx.fillStyle = 'rgba(0,0,0,0.08)';
                ctx.beginPath();
                ctx.ellipse(REAR_X + 6, REAR_Y + 8, REAR_R * 0.8, 6, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.beginPath();
                ctx.ellipse(FRONT_X + 6, FRONT_Y + 8, FRONT_R * 0.8, 6, 0, 0, Math.PI * 2);
                ctx.fill();

                // 水印/签名
                ctx.fillStyle = 'rgba(255,255,255,0.15)';
                ctx.font = '13px sans-serif';
                ctx.textAlign = 'right';
                ctx.fillText('🐦 海边骑行', W - 20, H - 16);

                requestAnimationFrame(animate);
            }

            // 启动动画
            requestAnimationFrame(animate);

            // 窗口大小自适应
            function resize() {
                const container = canvas.parentElement;
                const maxW = window.innerWidth * 0.92;
                const maxH = window.innerHeight * 0.92;
                const scale = Math.min(1, maxW / W, maxH / H);
                canvas.style.width = (W * scale) + 'px';
                canvas.style.height = (H * scale) + 'px';
            }
            window.addEventListener('resize', resize);
            resize();
        })();
    </script>
